const toAD = (be) => {
  const m = String(be || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return '';
  const y = +m[1], mo = +m[2], d = +m[3];
  if (y >= 9999 || mo < 1 || mo > 12 || d < 1 || d > 31) return '';   // 9999-99-99 / ไม่ระบุ → ว่าง
  return (y - 543) + '-' + m[2] + '-' + m[3];                          // พ.ศ. → ค.ศ.
};
