options.onValidate:
if (!value) return callback();
const tref = this.getFieldRef('id_type@row' + this.subFormRowId);
const t = tref ? tref.getValue() : null;

if (t === 'NI') {
  const cid = String(value).replace(/\D/g, '');
  if (cid.length !== 13) return callback(new Error('บัตรประชาชนต้อง 13 หลัก'));
  // เช็ค check digit (mod 11) — algorithm เดียวกับ validators.citizenId
  const rev = cid.split('').reverse().join('');
  let total = 0;
  for (let i = 1; i < 13; i++) total += Number(rev.charAt(i)) * (i + 1);
  const checkDigit = (11 - (total % 11)) % 10;
  if (Number(rev.charAt(0)) !== checkDigit)
    return callback(new Error('เลขบัตรประชาชนไม่ถูกต้อง'));
}
callback();

