this.$idLock = (refList) => {
  const rl = refList || {};
  const BASE = [
    { label: 'บัตรประชาชน',       value: 'NI'  },
    { label: 'หนังสือเดินทาง',     value: 'PPN' },
    { label: 'เลขเวชระเบียน (HN)', value: 'MR'  },
    { label: 'เลขอื่น/ไม่มีบัตร',   value: 'PI'  }
  ];
  const UNIQUE  = ['NI', 'PPN'];
  const FLATMAP = { '1': 'NI', '2': 'PPN' };
  const pRef = rl['p_idtype'];
  const flatType = pRef ? FLATMAP[pRef.getValue()] : null;
  const refs = Object.keys(rl)
    .filter((k) => k.indexOf('id_type@row') === 0)
    .map((k) => rl[k]).filter(Boolean);
  const vals = refs.map((r) => r.getValue());
  refs.forEach((r) => {
    const me = r.getValue();
    const used = new Set();
    if (flatType) used.add(flatType);
    vals.forEach((v) => { if (v && v !== me && UNIQUE.indexOf(v) >= 0) used.add(v); });
    r.setFieldOption('optionItems', BASE.map((o) => ({
      label: o.label, value: o.value,
      disabled: UNIQUE.indexOf(o.value) >= 0 && used.has(o.value)
    })));
  });
};

// ===== single source: recompute identity_keys + จัดการ dup/more_info =====
// เรียกจาก onFormDataChange (แก้ field) และ onSubFormRowChange (add/insert/delete row)
this.$syncIdentityKeys = (fieldName) => {
  const m = this.getFormData(false) || {};
  const norm = (s) => (s == null ? '' : String(s).replace(/[\s\-\/]/g, '').toLowerCase());

  const fresh = [];
  if (m.p_mom_cid && m.birth_date) {
    fresh.push('mom:' + norm(m.p_mom_cid) + '|' + norm(m.birth_date) + '|' + (m.birth_order || 0));
  }
  const it = m.p_idtype;
  if (it === '1' && m.p_cid)       fresh.push('th13:' + norm(m.p_cid));
  if (it === '5' && m.p_stateless) fresh.push('th13:' + norm(m.p_stateless));
  if (it === '2' && m.p_ppn)       fresh.push('ppn:'  + norm(m.p_ppn));
  if (it === '3' && m.p_foreign)   fresh.push('fid:'  + norm(m.p_foreign));
  const ids = Array.isArray(m.patient_ids) ? m.patient_ids : [];
  ids.forEach((row) => {
    const v = norm(row && row.id_value);
    if (!v) return;
    if (row.id_type === 'NI')       fresh.push('th13:' + v);
    else if (row.id_type === 'PPN') fresh.push('ppn:' + v);
  });

  const keys = Array.from(new Set(fresh));
  const sortJoin = (a) => a.slice().sort().join('|');
  const cur = this.getFieldValue('identity_keys') || [];
  if (sortJoin(cur) === sortJoin(keys)) return;   // ไม่เปลี่ยน → ไม่ทำอะไร

  this.setFieldValue('identity_keys', keys);
  if (!this.$idReady) return;                       // ข้าม initial load

  const hideIt = (name) => { const r = this.getFieldRef(name); if (r && typeof r.hide === 'function') r.hide(); };
  const dd = this.getFieldRef('vue_dedup'); if (dd) dd.vueState.candidates = [];
  hideIt('dup_box');

  // ซ่อน more_info เฉพาะตอนแก้ "บัตรหลัก" → บังคับ re-เช็คซ้ำ (sub-form อยู่ข้างใน more_info จึงไม่ซ่อน)
  const PRIMARY = ['p_idtype','p_cid','p_ppn','p_foreign','p_stateless','p_temp','p_mom_cid','birth_date','birth_order','p_twin'];
  if (PRIMARY.indexOf(fieldName) >= 0) hideIt('more_info');
};

